# Vulnerability details

## Description

When ```_blockAccount``` is called and the account that is getting blocked has balance in the market, escrow contract is created and balance of the user is transferred to this contract by updating ```_accounts``` mapping. When the account is unsanctioned, the balance that escrow contract owns has to be transferred back to the account. However there are no ways for transferring this balance back to the account unless borrower borrows all the balance available and gives them back in other way. Still this results in portion(reserve ratio) of funds getting locked permanently. 

## PoC

```solidity
// SPDX-License-Identifier: NONE
pragma solidity >=0.8.20;

import "forge-std/console.sol";

import './BaseMarketTest.sol';

contract Exploit is BaseMarketTest {
    function testBlockAccount() external {
        address carol = address(0xcccc);
        address escrow;

        _deposit(carol, 1e18);
        console.log("Carol's scaledBalance : %s", market.scaledBalanceOf(carol));

        // Carol is sanctioned and nukeFromOrbit(_blockAccount) is called to lock the asset
        sanctionsSentinel.sanction(carol);
        vm.recordLogs();
        market.nukeFromOrbit(carol);

        // Get escrow address
        Vm.Log[] memory entries = vm.getRecordedLogs();
        for (uint256 i=0; i<entries.length; i++) {
            if (entries[i].topics[0] == keccak256("Transfer(address,address,uint256)")) {
                escrow = address(uint160(uint256(entries[i].topics[2])));
            }
        }

        // Although Escrow contract's scaledBalance is updated, their is no way of transferring this balance. 
        console.log("Escrow contract scaledBalance : %s", market.scaledBalanceOf(escrow));
    }
}
```

