        for (uint256 i = 0; i < 36500; ++i) {
            fastForward(0.1 days);
            state = pendingState();
            updateState(state);
            market.updateState();
        }

        console.log("AFTER:");
        console.log("scaleFactor: ", state.scaleFactor);
        console.log(
